INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.73.1',
  '2026-08-06',
  'Фикс: нечитаемые выпадающие списки в тёмной теме на десктопе',
  E'В веб-версии Telegram на десктопе выпадающие списки в тёмной теме были нечитаемы: белый фон и светлый текст. В мини-аппе на телефоне и в обычном браузере всё было нормально, поэтому и не бросалось в глаза.\n\nПричин оказалось две. Приложение не сообщало браузеру, что тема тёмная, и он рисовал родные элементы — список <select>, полосы прокрутки, автозаполнение — светлой палитрой. Плюс фон полей местами задавался полупрозрачным, а вебвью подкладывает под родной элемент свой белый фон.\n\nТеперь тёмность определяется по яркости фона темы (своя тема бывает тёмной, хотя заведена как светлая), а поля ввода везде с непрозрачным фоном.',
  E'applyTokens ставит на <html> color-scheme по luminance(tokens.bg) < 0.4, а не по kind: своя тема может быть тёмной при kind=light. То же правило продублировано в theme.css на :root[data-theme], чтобы родные элементы не мигали светлыми до применения токенов из JS. Добавлены явные цвета для option/optgroup: на части движков color-scheme до пунктов списка не доходит.\n\nПоля ввода переведены с var(--card-color) (rgba с --card-alpha) на непрозрачный var(--bg-secondary) в 7 компонентах; глобальное правило в theme.css расширено на textarea.\n\nПоймано при правке: замена по регулярке зацепила три КАРТОЧКИ (.check-group, .section, .proj) — «селектором» блока оказался хвост <script>, где встречались слова input/select. Откачено, замена перепроверена разбором только секции <style> и только правил, чей селектор — поле; повторная проверка показала 0 оставшихся полей на полупрозрачном фоне.\n\nПроверено в браузере: color-scheme=dark на <html>, 4 селекта на вкладке «Траты» и 7 полей в модалке — фон rgb(43,43,43), текст rgb(224,224,224), полупрозрачных нет; CSS-правило для data-theme=light даёт color-scheme=light.'
);
